const conMod = Math.floor(((monster.stats?.[2] ?? 10) - 10) / 2);

const hitpoints = String(monster.hp ?? "").replace(/[\u200B-\u200E\uFEFF]/g, "");

let diceStr = "";
let conAdj = null;   // null means "no dice / no adjustment"
let conStr = "";

if (monster.hit_dice) {
  const m = String(monster.hit_dice).match(/\b\d{1,2}d\d{1,3}\b/);
  if (m) {
    diceStr = m[0]; // e.g. "6d8"
    const numDice = parseInt(diceStr.split("d")[0], 10);

    conAdj = numDice * conMod; // can be negative, zero, or positive
    conStr = conAdj === 0 ? "" : (conAdj > 0 ? `+ ${conAdj}` : `- ${Math.abs(conAdj)}`);
  }
}

if (!diceStr) {
  return `${hitpoints}`;
} else if (conAdj === 0) {
  return `${hitpoints} (${diceStr})`;
} else {
  return `${hitpoints} (${diceStr} ${conStr})`;
}

