const modCol = "#c8b8d4";
const saveCol = "#c5a8cd";

// Define abbreviations for display and full names for matching.
const statAbbr = ["Str", "Dex", "Con", "Int", "Wis", "Cha"];
const statNames = ["strength", "dexterity", "constitution", "intelligence", "wisdom", "charisma"];

// Helper function to format modifiers.
function formatMod(val) {
  return val >= 0 ? `+${val}` : `-${Math.abs(val)}`;
}

// --- Define CSS Styles ---
const styleContent = `
  /* General table styling */
  table.stat-table {
    border-collapse: collapse;
    width: 100%;
    table-layout: fixed;
    border: 5px solid var(--statblock-background-color);
    box-sizing: border-box; /* important: include borders in width math */
  }

  table.stat-table th,
  table.stat-table td {
    padding: 5px;
    border: 5px solid var(--statblock-background-color);
    text-align: center !important;
    vertical-align: middle; /* FIX: 'center' is invalid */
    box-sizing: border-box;  /* important: include borders/padding in cell sizing */
    white-space: nowrap;     /* prevent odd wrapping */
  }

  /* Style for header cells */
  table.stat-table th.header-cell {
    color: var(--statblock-primary-color);
    font-size: 0.5em;
  }

  /* Style for ability abbreviation cells */
  table.stat-table td.ability-abbr-cell {
    color: var(--statblock-rule-color);
    font-weight: bold;
  }

  /* Style for modifier cells */
  table.stat-table td.modifier-cell {
    background-color: ${modCol};
    color: var(--statblock-primary-color);
  }

  /* Style for saving throw cells */
  table.stat-table td.saving-throw-cell {
    background-color: ${saveCol};
    color: var(--statblock-primary-color);
  }
`;

// Create a <style> element and append it to the document head (only once if possible).
const STYLE_ID = "stat-table-style";
if (!document.getElementById(STYLE_ID)) {
  const styleElement = document.createElement("style");
  styleElement.id = STYLE_ID;
  styleElement.textContent = styleContent;
  document.head.appendChild(styleElement);
}

// --- Create the Table ---
const table = document.createElement("table");
table.classList.add("stat-table");

// Force equal widths across all 9 columns (3 blocks × [abbr, mod, save])
const colgroup = document.createElement("colgroup");
for (let i = 0; i < 9; i++) {
  const col = document.createElement("col");
  col.style.width = `${100 / 9}%`;
  colgroup.appendChild(col);
}
table.appendChild(colgroup);

// --- Header Row ---
const headerRow = document.createElement("tr");
for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    const headerCell = document.createElement("th");
    headerCell.textContent = j === 0 ? "" : j === 1 ? "Mod" : "Save";
    headerCell.classList.add("header-cell");
    headerRow.appendChild(headerCell);
  }
}
table.appendChild(headerRow);

// --- Data Rows ---
for (let rowIndex = 0; rowIndex < 2; rowIndex++) {
  const row = document.createElement("tr");

  for (let colIndex = 0; colIndex < 3; colIndex++) {
    const statIndex = rowIndex * 3 + colIndex;
    if (statIndex >= statAbbr.length) break;

    // Ability abbreviation cell.
    const abilityCell = document.createElement("td");
    abilityCell.textContent = statAbbr[statIndex];
    abilityCell.classList.add("ability-abbr-cell");
    row.appendChild(abilityCell);

    // Ability modifier cell.
    const statMod = Math.floor((monster.stats[statIndex] - 10) / 2);
    const modCell = document.createElement("td");
    modCell.textContent = formatMod(statMod);
    modCell.classList.add("modifier-cell");
    row.appendChild(modCell);

    // Saving throw modifier cell.
    const saveObj = (monster.saves ?? []).find(s => {
      const key = Object.keys(s)[0].toLowerCase();
      return key === statNames[statIndex];
    });
    const saveMod = saveObj ? Object.values(saveObj)[0] : statMod;

    const saveModCell = document.createElement("td");
    saveModCell.textContent = formatMod(saveMod);
    saveModCell.classList.add("saving-throw-cell");
    row.appendChild(saveModCell);
  }

  table.appendChild(row);
}

// Return the created table element so it can be attached to the block's container.
return table;

